-- patroclus -- neovim colorscheme.
--
-- GENERATED by tools/gen_tokens.py in the patroclus repo, from its
-- design.yaml. Do not edit here; change design.yaml and regenerate.
--
-- Dark only: patroclus's light palette is for paper and the web, and an
-- editor that follows `background` would need a second full mapping.

vim.cmd("highlight clear")
if vim.fn.exists("syntax_on") == 1 then
  vim.cmd("syntax reset")
end

vim.o.background = "dark"
vim.g.colors_name = "patroclus"

